function node(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function button(text,fn,cls='button'){const b=node('button',cls,text);b.type='button';b.addEventListener('click',fn);return b;}
function notice(text,error=false){$('notice').hidden=!text;$('notice').textContent=text;$('notice').classList.toggle('error',error);}
function money(value){const text=String(value),negative=text.startsWith('-'),[whole,fraction='00']=(negative?text.slice(1):text).split('.');return (negative?'-':'')+'₹'+BigInt(whole).toLocaleString('en-IN')+'.'+fraction.padEnd(2,'0');}
function paise(value){const n=BigInt(value);return money((n/100n).toString()+'.'+(n%100n).toString().padStart(2,'0'));}
function time(value){return new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});}
function locked(){return ui.busy||Boolean(ui.pending);}
function lock(){for(const b of document.querySelectorAll('button,input,select,textarea')){if(b.id==='retry')b.disabled=ui.busy;else if(locked()){if(b.dataset.wasDisabled===undefined)b.dataset.wasDisabled=String(b.disabled);b.disabled=true;}else if(b.dataset.wasDisabled!==undefined){b.disabled=b.dataset.wasDisabled==='true';delete b.dataset.wasDisabled;}}$('pending').hidden=!ui.pending;}
async function api(path,{method='GET',body}={}){const headers={};if(method==='POST'){headers['X-CSRF-Token']=ui.csrf;if(body!==undefined)headers['Content-Type']='application/json';}const response=await fetch(path,{method,headers,credentials:'same-origin',cache:'no-store',body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok){const e=new Error(errors[data.status]||data.status?.replaceAll('_',' ').toLowerCase()||'Request unavailable.');e.known=data.retry_same_request!==true;e.status=response.status;e.code=data.status;throw e;}return data;}
async function mutate(path,payload,after){if(locked())return;return execute({path,payload,after});}
async function execute(action){ui.busy=true;lock();let accepted=false;try{const receipt=await api(action.path,{method:'POST',body:action.payload});accepted=true;ui.pending=null;await action.after(receipt);notice(receipt.status==='REPLAYED'?'Earlier action already accepted. Current saved information is shown.':'Saved. Review the current draft before continuing.');}catch(e){if(accepted||!e.known){ui.pending=action;notice('The current outcome needs a refresh. Retry the exact action; later changes will be preserved.',true);}else{ui.pending=null;notice(e.message,true);if(e.status===409&&ui.case){try{await openCase(ui.case.id);}catch{}}if(e.status===401)showAuth('login');}}finally{ui.busy=false;lock();}}
function field(label,value='',type='text'){const l=node('label','',label),input=node('input');input.type=type;input.value=value;l.append(input);return {label:l,input};}
function select(label,options,value){const l=node('label','',label),input=node('select');input.setAttribute('aria-label',label);for(const [v,t]of options){const o=node('option','',t);o.value=v;input.append(o);}input.value=value;l.append(input);return {label:l,input};}
function check(text){const l=node('label','check-label'),input=node('input');input.type='checkbox';l.append(input,document.createTextNode(text));return {label:l,input};}
function section(title,description){const card=node('section','card');card.append(node('h2','',title));if(description)card.append(node('p','muted',description));return card;}
function empty(title,description){const box=node('div','empty');box.append(node('h3','',title),node('p','',description));return box;}
function table(headers,rows){const wrap=node('div','table-wrap'),t=node('table'),head=node('thead'),tr=node('tr');headers.forEach(x=>tr.append(node('th','',x)));head.append(tr);const body=node('tbody');for(const row of rows){const tr=node('tr');for(const cell of row){const td=node('td');td.append(cell instanceof Node?cell:document.createTextNode(String(cell)));tr.append(td);}body.append(tr);}t.append(head,body);wrap.append(t);return wrap;}
function heading(title,description,eyebrow='YOUR WORKSPACE'){$('page-title').textContent=title;$('page-description').textContent=description;$('page-eyebrow').textContent=eyebrow;$('breadcrumb').textContent='Workspace / '+title;}
function content(...nodes){$('page-content').replaceChildren(...nodes);}
