async function navigate(page){ui.busy=true;lock();ui.page=page;ui.case=null;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));try{switch(page){case 'overview':case 'cases':await renderCases(page);break;case 'commercial':await commercial();break;case 'support':await support();break;case 'feedback':await feedbackPage();break;case 'experts':await expertsPage();break;case 'audit':await activity();break;case 'admin':await administration();break;case 'readiness':readiness();break;case 'security':await securityPage();break;case 'privacy':await privacyPage();break;}}catch(e){notice(e.message,true);}finally{ui.busy=false;lock();}}
async function renderCases(page){ui.cases=(await api('/api/cases')).cases;const isTeam=ui.user.role==='PREPARER';heading(isTeam?'Your preparation queue.':page==='overview'?'Your preparation, together.':'Your saved drafts.',isTeam?'Only drafts with active, specific preparation access appear here.':'Prepare the facts, check the sources and keep the next step clear.');const nodes=[];if(page==='overview'){const metrics=node('div','metrics');for(const [value,label,help]of [[ui.cases.length,isTeam?'Shared drafts':'Saved drafts','Current account access'],[ui.cases.filter(c=>c.confirmed_fields===4).length,'Income prepared','Four fields confirmed'],['Pending','Tax validation','Independent approval required']]){const card=node('div','metric');card.append(node('span','',label),node('strong','',String(value)),node('p','',help));metrics.append(card);}nodes.push(metrics,node('div','banner','This development release saves sample data locally. Preparation progress does not release numerical tax results, authorize professional sign-off or enable filing.'));}const head=node('div','section-head');head.append(node('h2','',isTeam?'Drafts shared with you':'Continue preparing'));nodes.push(head);const grid=node('div','case-grid');for(const item of ui.cases){const card=node('article','card case-card'),meta=node('div','card-meta');meta.append(node('span','',item.period),node('span','badge',item.archived?'Archived':item.confirmed_fields+'/4 confirmed'));card.append(meta,node('h3','',item.title),node('p','muted','Updated '+time(item.updated_at)),button('Open draft →',()=>safe(()=>openCase(item.id)),'text-button'));grid.append(card);}if(!ui.cases.length)grid.append(empty(isTeam?'No shared drafts yet.':'Start with one clear draft.',isTeam?'A customer must explicitly share a case with this preparation account.':'Create a sample salary and interest case. Every missing value remains unknown.'));nodes.push(grid);content(...nodes);}
