$('auth-form').addEventListener('submit',async e=>{e.preventDefault();if(locked())return;ui.busy=true;lock();try{const authSession=await api('/api/bootstrap');ui.csrf=authSession.csrf_token;const payload={username:$('auth-username').value,password:$('auth-password').value};if(ui.authMode==='register')payload.display_name=$('auth-display').value;const data=await api('/api/'+ui.authMode,{method:'POST',body:payload});ui.csrf=data.csrf_token;ui.user=data.user;$('auth-form').reset();if(data.mfa_required){showFactor();notice('Enter a fresh authenticator code or an unused recovery code.');}else{shell();await navigate(data.operator_mfa_enrollment_required?'security':'overview');notice('Workspace opened. Use synthetic information only.');}}catch(e){notice(e.known?e.message:'The sign-in response was interrupted. Refresh and sign in to check your account; avoid creating another registration.',true);}finally{ui.busy=false;lock();if(!$('factor-panel').hidden)$('factor-code').focus();}});
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{if(!locked())safe(()=>navigate(b.dataset.page));}));$('new-case-top').addEventListener('click',()=>{if(!locked())$('create-dialog').showModal();});$('create-cancel').addEventListener('click',()=>$('create-dialog').close());$('create-form').addEventListener('submit',e=>{e.preventDefault();$('create-dialog').close();mutate('/api/cases',{title:$('new-case-title').value,request_id:crypto.randomUUID()},r=>openCase(r.id,'income'));});$('retry').addEventListener('click',()=>{if(ui.pending&&!ui.busy)execute(ui.pending);});$('refresh').addEventListener('click',()=>safe(()=>ui.case?openCase(ui.case.id):navigate(ui.page)));const signOut=()=>safe(async()=>{if(locked())return;await api('/api/logout',{method:'POST'});ui.user=null;ui.case=null;$('login-top').hidden=false;$('register-top').hidden=false;$('logout-top').hidden=true;await bootstrap();notice('Signed out. Saved sample drafts remain on this local installation.');});$('logout').addEventListener('click',signOut);$('logout-top').addEventListener('click',signOut);$('public-readiness').addEventListener('click',()=>{if(ui.user){shell();navigate('readiness');}else{showAuth('login');notice('Accounts and sample workflows run locally. Tax references, live payments and filing are pending.');}});
