 box.append(section('Prepare an ITR draft yourself.','This is a narrow preparation check for FY 2025–26 / AY 2026–27. It does not select a statutory ITR form or approve tax figures. A specialist workflow is needed for uncovered scope; this screen does not determine whether a CA is legally required.'));
 const card=section('Review your scope',data.scope_review_current?'Declarations match the current draft.':'Review again after changing inputs, profile, documents or source review.'),form=node('form'),inputs={};
 for(const [key,label]of Object.entries(data.questions)){const control=select(label,[['UNKNOWN','Not checked / unsure'],['YES','Yes'],['NO','No']],data.answers[key]);inputs[key]=control.input;form.append(control.label);}
 const consent=check('I reviewed these scope declarations against this current draft. Unknown answers remain unknown.'),save=button('Save scope declarations',()=>{});save.type='submit';form.append(consent.label,save);form.addEventListener('submit',e=>{e.preventDefault();const answers=Object.fromEntries(Object.entries(inputs).map(([key,input])=>[key,input.value]));mutate('/api/cases/'+c.id+'/itr-scope',{request_id:crypto.randomUUID(),expected_revision:c.revision,period:data.period,answers,answers_reviewed:consent.input.checked},()=>openCase(c.id,'itr'));});card.append(form);
 const progress=section(data.status.replaceAll('_',' '),'Document availability is declared, not authenticated. Complete the income, profile and checklist tabs as the tasks require.');progress.append(table(['Task','Status','Next step'],data.tasks.map(t=>[t.code.replaceAll('_',' '),t.status.replaceAll('_',' '),t.message])));
