  const taxpayer=check('I checked outside this preview that this source and draft refer to the same synthetic taxpayer. Identity is not verified here.');choices.append(taxpayer.label);const save=button('Create selected income proposals',()=>{const selections=controls.filter(x=>x.include.input.checked).map(x=>({field:x.proposal.field,amount:x.proposal.amount,whole_category_confirmed:x.whole.input.checked,replace_input_confirmed:x.replace.input.checked}));mutate('/api/cases/'+c.id+'/itr-native-propose',{request_id:crypto.randomUUID(),expected_revision:c.revision,preview_id:data.preview_id,same_taxpayer_confirmed:taxpayer.input.checked,selections},()=>openCase(c.id,'income'));});save.disabled=true;const ready=()=>{const selected=controls.filter(x=>x.include.input.checked);save.disabled=c.archived||!taxpayer.input.checked||!selected.length||selected.some(x=>!x.whole.input.checked||!x.replace.input.checked);};for(const x of controls)for(const control of [x.include,x.whole,x.replace])control.input.addEventListener('change',ready);taxpayer.input.addEventListener('change',ready);choices.append(save,button('Discard preview',()=>safe(async()=>{await api('/api/cases/'+c.id+'/itr-native-discard',{method:'POST',body:{expected_revision:c.revision,preview_id:data.preview_id}});results.replaceChildren();notice('Preview discarded. Saved inputs were not changed.');}),'secondary'));results.append(choices);
